import React, { useState, useMemo } from 'react';
import Navbar from './components/Navbar';
import PropertyCard from './components/PropertyCard';
import BookingModal from './components/BookingModal';
import { MOCK_HOUSES, MOCK_USERS } from './constants';
import { House, UserRole, Booking, SearchFilters, User } from './types';
import { Search, Filter, CheckCircle2, XCircle, Clock, LayoutGrid, List } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]);
  const [houses, setHouses] = useState<House[]>(MOCK_HOUSES);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedHouse, setSelectedHouse] = useState<House | null>(null);

  // Filter States
  const [filters, setFilters] = useState<SearchFilters>({
    location: '',
    minPrice: '',
    maxPrice: '',
    type: 'All',
    bedrooms: '',
    amenities: []
  });

  // Filter Logic
  const filteredHouses = useMemo(() => {
    return houses.filter(h => {
      const matchLoc = h.location.toLowerCase().includes(filters.location.toLowerCase());
      const matchMin = filters.minPrice === '' || h.price >= filters.minPrice;
      const matchMax = filters.maxPrice === '' || h.price <= filters.maxPrice;
      const matchType = filters.type === 'All' || h.type === filters.type;
      const matchBeds = filters.bedrooms === '' || h.bedrooms === Number(filters.bedrooms);
      return matchLoc && matchMin && matchMax && matchType && matchBeds;
    });
  }, [houses, filters]);

  const handleBookingSubmit = (startDate: string, endDate: string) => {
    if (!selectedHouse) return;

    const newBooking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      houseId: selectedHouse.id,
      tenantId: currentUser.id,
      status: 'PENDING',
      startDate,
      endDate,
      totalPrice: selectedHouse.price, // Simplified for demo
      createdAt: new Date().toISOString()
    };

    setBookings([newBooking, ...bookings]);
    setSelectedHouse(null);
    alert('Booking request sent successfully!');
  };

  const updateBookingStatus = (bookingId: string, status: Booking['status']) => {
    setBookings(prev => prev.map(b => b.id === bookingId ? { ...b, status } : b));

    // If confirmed, update house availability
    if (status === 'CONFIRMED') {
      const booking = bookings.find(b => b.id === bookingId);
      if (booking) {
        setHouses(prev => prev.map(h => h.id === booking.houseId ? { ...h, isAvailable: false } : h));
      }
    }
  };

  const toggleHouseAvailability = (houseId: string) => {
    setHouses(prev => prev.map(h => h.id === houseId ? { ...h, isAvailable: !h.isAvailable } : h));
  };

  // Views
  const renderMarketplace = () => (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Find your next home</h1>
        <p className="mt-2 text-gray-500">Discover premium properties managed by verified landlords and agents.</p>
      </div>

      {/* Advanced Filter Bar */}
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6 mb-10">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Location</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <input 
                type="text" 
                placeholder="Where do you want to live?"
                value={filters.location}
                onChange={e => setFilters({...filters, location: e.target.value})}
                className="w-full pl-10 pr-4 py-2 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Property Type</label>
            <select 
              value={filters.type}
              onChange={e => setFilters({...filters, type: e.target.value})}
              className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
            >
              <option>All</option>
              <option>Apartment</option>
              <option>House</option>
              <option>Studio</option>
              <option>Villa</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Bedrooms</label>
            <select 
              value={filters.bedrooms}
              onChange={e => setFilters({...filters, bedrooms: e.target.value === '' ? '' : Number(e.target.value)})}
              className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
            >
              <option value="">Any</option>
              <option value="1">1 Bed</option>
              <option value="2">2 Beds</option>
              <option value="3">3 Beds</option>
              <option value="4">4+ Beds</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Price Range</label>
            <div className="flex items-center gap-2">
              <input 
                type="number" 
                placeholder="Min"
                value={filters.minPrice}
                onChange={e => setFilters({...filters, minPrice: e.target.value === '' ? '' : Number(e.target.value)})}
                className="w-full px-3 py-2 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              />
              <span className="text-gray-300">-</span>
              <input 
                type="number" 
                placeholder="Max"
                value={filters.maxPrice}
                onChange={e => setFilters({...filters, maxPrice: e.target.value === '' ? '' : Number(e.target.value)})}
                className="w-full px-3 py-2 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Results Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
        {filteredHouses.length > 0 ? (
          filteredHouses.map(house => (
            <PropertyCard 
              key={house.id} 
              house={house} 
              onClick={(h) => h.isAvailable && setSelectedHouse(h)} 
            />
          ))
        ) : (
          <div className="col-span-full py-20 text-center">
            <div className="bg-gray-100 h-20 w-20 rounded-full flex items-center justify-center mx-auto mb-4">
              <Search className="h-8 w-8 text-gray-400" />
            </div>
            <h3 className="text-lg font-bold text-gray-900">No properties found</h3>
            <p className="text-gray-500">Try adjusting your filters to find more results.</p>
          </div>
        )}
      </div>
    </div>
  );

  const renderDashboard = () => (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-10">
        <div>
          <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Management Center</h1>
          <p className="mt-2 text-gray-500">Monitor your properties and manage incoming booking requests.</p>
        </div>
        <div className="flex items-center gap-3">
          <button className="px-5 py-2.5 bg-indigo-600 text-white font-semibold rounded-xl hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100">
            List New Property
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Bookings Section */}
        <div className="lg:col-span-2 space-y-6">
          <div className="flex items-center justify-between mb-2">
            <h2 className="text-xl font-bold text-gray-900">Recent Requests</h2>
            <span className="bg-indigo-100 text-indigo-700 text-xs font-bold px-2 py-1 rounded-full">
              {bookings.filter(b => b.status === 'PENDING').length} New
            </span>
          </div>

          <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
            {bookings.length > 0 ? (
              <div className="divide-y divide-gray-100">
                {bookings.map(booking => {
                  const house = houses.find(h => h.id === booking.houseId);
                  const tenant = MOCK_USERS.find(u => u.id === booking.tenantId);
                  return (
                    <div key={booking.id} className="p-6 hover:bg-gray-50 transition-colors">
                      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                        <div className="flex items-center gap-4">
                          <img src={tenant?.avatar} className="h-12 w-12 rounded-full border-2 border-white shadow-sm" alt="" />
                          <div>
                            <p className="font-bold text-gray-900">{tenant?.name}</p>
                            <p className="text-xs text-gray-500">{house?.title}</p>
                          </div>
                        </div>

                        <div className="flex flex-wrap items-center gap-3">
                          <div className="bg-gray-100 px-3 py-1.5 rounded-lg text-xs font-medium text-gray-600">
                            {new Date(booking.startDate).toLocaleDateString()} - {new Date(booking.endDate).toLocaleDateString()}
                          </div>

                          {booking.status === 'PENDING' ? (
                            <div className="flex gap-2">
                              <button 
                                onClick={() => updateBookingStatus(booking.id, 'CONFIRMED')}
                                className="p-2 bg-green-50 text-green-600 hover:bg-green-100 rounded-lg transition-colors"
                              >
                                <CheckCircle2 className="h-5 w-5" />
                              </button>
                              <button 
                                onClick={() => updateBookingStatus(booking.id, 'REJECTED')}
                                className="p-2 bg-red-50 text-red-600 hover:bg-red-100 rounded-lg transition-colors"
                              >
                                <XCircle className="h-5 w-5" />
                              </button>
                            </div>
                          ) : (
                            <span className={`px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wider ${
                              booking.status === 'CONFIRMED' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                            }`}>
                              {booking.status}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="p-10 text-center text-gray-400">
                <Clock className="h-10 w-10 mx-auto mb-4 opacity-20" />
                <p>No booking requests yet.</p>
              </div>
            )}
          </div>
        </div>

        {/* Inventory Section */}
        <div className="space-y-6">
          <h2 className="text-xl font-bold text-gray-900">My Properties</h2>
          <div className="space-y-4">
            {houses.filter(h => h.ownerId === currentUser.id || h.agentId === currentUser.id).map(house => (
              <div key={house.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <img src={house.images[0]} className="h-14 w-14 rounded-xl object-cover" alt="" />
                  <div>
                    <h4 className="text-sm font-bold text-gray-900 leading-tight">{house.title}</h4>
                    <p className="text-xs text-gray-500">${house.price}/mo</p>
                  </div>
                </div>
                <button 
                  onClick={() => toggleHouseAvailability(house.id)}
                  className={`relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${
                    house.isAvailable ? 'bg-green-500' : 'bg-gray-200'
                  }`}
                >
                  <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${
                    house.isAvailable ? 'translate-x-5' : 'translate-x-0'
                  }`} />
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-20">
      <Navbar 
        currentRole={currentUser.role} 
        currentUser={currentUser}
        onRoleChange={(role) => {
          const newUser = MOCK_USERS.find(u => u.role === role) || MOCK_USERS[0];
          setCurrentUser(newUser);
        }}
      />

      {currentUser.role === 'TENANT' ? renderMarketplace() : renderDashboard()}

      {selectedHouse && (
        <BookingModal 
          house={selectedHouse} 
          user={currentUser}
          onClose={() => setSelectedHouse(null)}
          onSubmit={handleBookingSubmit}
        />
      )}

      {/* Persistent Mobile Tab Bar (Contextual) */}
      <div className="fixed bottom-0 left-0 right-0 glass border-t border-gray-200 p-3 md:hidden flex justify-around">
        <button className="p-2 text-indigo-600 flex flex-col items-center">
          <LayoutGrid className="h-6 w-6" />
          <span className="text-[10px] font-bold mt-1">Explore</span>
        </button>
        <button className="p-2 text-gray-400 flex flex-col items-center">
          <Clock className="h-6 w-6" />
          <span className="text-[10px] font-bold mt-1">Bookings</span>
        </button>
        <button className="p-2 text-gray-400 flex flex-col items-center">
          <Filter className="h-6 w-6" />
          <span className="text-[10px] font-bold mt-1">Filters</span>
        </button>
      </div>
    </div>
  );
};

export default App;

export type UserRole = 'TENANT' | 'LANDLORD' | 'AGENT';
export type Page = 'MARKETPLACE' | 'DASHBOARD' | 'ABOUT' | 'CONTACT' | 'MY_BOOKINGS';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar: string;
}

export interface House {
  id: string;
  title: string;
  description: string;
  price: number;
  location: string;
  type: 'Apartment' | 'House' | 'Studio' | 'Villa';
  bedrooms: number;
  bathrooms: number;
  images: string[];
  isAvailable: boolean;
  amenities: string[];
  ownerId: string;
  agentId?: string;
}

export interface Booking {
  id: string;
  houseId: string;
  tenantId: string;
  status: 'PENDING' | 'CONFIRMED' | 'REJECTED' | 'CANCELLED';
  startDate: string;
  endDate: string;
  totalPrice: number;
  createdAt: string;
}

export interface SearchFilters {
  location: string;
  minPrice: number | '';
  maxPrice: number | '';
  type: string;
  bedrooms: number | '';
  amenities: string[];
}

