import React, { useState, useMemo } from 'react';
import Navbar from './components/Navbar';
import PropertyCard from './components/PropertyCard';
import BookingModal from './components/BookingModal';
import AboutUs from './components/AboutUs';
import ContactUs from './components/ContactUs';
import { MOCK_HOUSES, MOCK_USERS } from './constants';
import { House, UserRole, Booking, SearchFilters, User, Page } from './types';
import { Search, Filter, CheckCircle2, XCircle, Clock, LayoutGrid, List, User as UserIcon, Building2, MapPin, Calendar } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]);
  const [currentPage, setCurrentPage] = useState<Page>('MARKETPLACE');
  const [houses, setHouses] = useState<House[]>(MOCK_HOUSES);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedHouse, setSelectedHouse] = useState<House | null>(null);

  // Filter States
  const [filters, setFilters] = useState<SearchFilters>({
    location: '',
    minPrice: '',
    maxPrice: '',
    type: 'All',
    bedrooms: '',
    amenities: []
  });

  // Filter Logic
  const filteredHouses = useMemo(() => {
    return houses.filter(h => {
      const matchLoc = h.location.toLowerCase().includes(filters.location.toLowerCase());
      const matchMin = filters.minPrice === '' || h.price >= filters.minPrice;
      const matchMax = filters.maxPrice === '' || h.price <= filters.maxPrice;
      const matchType = filters.type === 'All' || h.type === filters.type;
      const matchBeds = filters.bedrooms === '' || h.bedrooms === Number(filters.bedrooms);
      return matchLoc && matchMin && matchMax && matchType && matchBeds;
    });
  }, [houses, filters]);

  const handleBookingSubmit = (startDate: string, endDate: string) => {
    if (!selectedHouse) return;

    const newBooking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      houseId: selectedHouse.id,
      tenantId: currentUser.id,
      status: 'PENDING',
      startDate,
      endDate,
      totalPrice: selectedHouse.price, 
      createdAt: new Date().toISOString()
    };

    setBookings([newBooking, ...bookings]);
    setSelectedHouse(null);
    setCurrentPage('MY_BOOKINGS');
  };

  const updateBookingStatus = (bookingId: string, status: Booking['status']) => {
    setBookings(prev => prev.map(b => b.id === bookingId ? { ...b, status } : b));

    if (status === 'CONFIRMED') {
      const booking = bookings.find(b => b.id === bookingId);
      if (booking) {
        setHouses(prev => prev.map(h => h.id === booking.houseId ? { ...h, isAvailable: false } : h));
      }
    }
  };

  const toggleHouseAvailability = (houseId: string) => {
    setHouses(prev => prev.map(h => h.id === houseId ? { ...h, isAvailable: !h.isAvailable } : h));
  };

  // Views
  const renderMarketplace = () => (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Find your next home</h1>
          <p className="mt-2 text-gray-500">Discover premium properties managed by verified landlords and agents.</p>
        </div>
        <div className="flex items-center gap-2 text-sm text-gray-400 font-medium">
          <span className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-full">{filteredHouses.length} properties found</span>
        </div>
      </div>

      {/* Advanced Filter Bar */}
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6 mb-10 sticky top-20 z-40 transition-shadow hover:shadow-md">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Location</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <input 
                type="text" 
                placeholder="City, neighborhood..."
                value={filters.location}
                onChange={e => setFilters({...filters, location: e.target.value})}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-transparent rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Type</label>
            <select 
              value={filters.type}
              onChange={e => setFilters({...filters, type: e.target.value})}
              className="w-full px-4 py-2.5 bg-gray-50 border-transparent rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            >
              <option>All</option>
              <option>Apartment</option>
              <option>House</option>
              <option>Studio</option>
              <option>Villa</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Beds</label>
            <select 
              value={filters.bedrooms}
              onChange={e => setFilters({...filters, bedrooms: e.target.value === '' ? '' : Number(e.target.value)})}
              className="w-full px-4 py-2.5 bg-gray-50 border-transparent rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            >
              <option value="">Any</option>
              <option value="1">1 Bed</option>
              <option value="2">2 Beds</option>
              <option value="3">3 Beds</option>
              <option value="4">4+ Beds</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Price Range</label>
            <div className="flex items-center gap-2">
              <input 
                type="number" 
                placeholder="Min"
                value={filters.minPrice}
