                className="w-full px-3 py-2.5 bg-gray-50 border-transparent rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              />
              <span className="text-gray-300">-</span>
              <input 
                type="number" 
                placeholder="Max"
                value={filters.maxPrice}
                onChange={e => setFilters({...filters, maxPrice: e.target.value === '' ? '' : Number(e.target.value)})}
                className="w-full px-3 py-2.5 bg-gray-50 border-transparent rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              />
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
        {filteredHouses.length > 0 ? (
          filteredHouses.map(house => (
            <PropertyCard 
              key={house.id} 
              house={house} 
              onClick={(h) => h.isAvailable && setSelectedHouse(h)} 
            />
          ))
        ) : (
          <div className="col-span-full py-20 text-center">
            <div className="bg-gray-100 h-20 w-20 rounded-full flex items-center justify-center mx-auto mb-4">
              <Search className="h-8 w-8 text-gray-400" />
            </div>
            <h3 className="text-lg font-bold text-gray-900">No matches found</h3>
            <p className="text-gray-500">Try loosening your search criteria or changing the location.</p>
          </div>
        )}
      </div>
    </div>
  );

  const renderDashboard = () => (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-10">
        <div>
          <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Management Dashboard</h1>
          <p className="mt-2 text-gray-500">
            {currentUser.role === 'LANDLORD' ? 'Manage your property portfolio.' : 'Oversee assigned properties and client requests.'}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100 flex items-center gap-2">
            <Building2 className="w-5 h-5" />
            Add Property
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-gray-900">Incoming Requests</h2>
              <span className="bg-amber-100 text-amber-700 text-xs font-bold px-3 py-1 rounded-full uppercase tracking-wider">
                Action Required
              </span>
            </div>

            <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
              {bookings.filter(b => b.status === 'PENDING').length > 0 ? (
                <div className="divide-y divide-gray-100">
                  {bookings.filter(b => b.status === 'PENDING').map(booking => {
                    const house = houses.find(h => h.id === booking.houseId);
                    const tenant = MOCK_USERS.find(u => u.id === booking.tenantId);
                    return (
                      <div key={booking.id} className="p-6 hover:bg-gray-50 transition-colors">
                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
                          <div className="flex items-center gap-4">
                            <div className="relative">
                              <img src={tenant?.avatar} className="h-14 w-14 rounded-full border-2 border-white shadow-md" alt="" />
                              <div className="absolute -bottom-1 -right-1 bg-green-500 border-2 border-white w-4 h-4 rounded-full"></div>
                            </div>
                            <div>
                              <p className="font-bold text-gray-900 text-lg leading-tight">{tenant?.name}</p>
                              <p className="text-sm text-indigo-600 font-medium">{house?.title}</p>
                            </div>
                          </div>

                          <div className="flex flex-col sm:items-end gap-2">
                            <div className="flex items-center text-xs font-bold text-gray-500 gap-2 mb-1">
                              <Calendar className="w-3.5 h-3.5" />
                              {new Date(booking.startDate).toLocaleDateString()} — {new Date(booking.endDate).toLocaleDateString()}
                            </div>
                            <div className="flex gap-2">
                              <button 
                                onClick={() => updateBookingStatus(booking.id, 'CONFIRMED')}
                                className="px-4 py-2 bg-green-600 text-white hover:bg-green-700 rounded-xl transition-colors font-bold text-sm flex items-center gap-1.5"
                              >
                                <CheckCircle2 className="h-4 w-4" />
                                Approve
                              </button>
                              <button 
                                onClick={() => updateBookingStatus(booking.id, 'REJECTED')}
                                className="px-4 py-2 bg-white text-red-600 border border-red-100 hover:bg-red-50 rounded-xl transition-colors font-bold text-sm flex items-center gap-1.5"
                              >
                                <XCircle className="h-4 w-4" />
                                Decline
                              </button>
                            </div>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div className="p-16 text-center text-gray-400">
                  <div className="bg-gray-50 h-16 w-16 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                    <Clock className="h-6 w-6 text-gray-300" />
                  </div>
                  <p className="font-medium text-gray-500">Inbox is empty</p>
                  <p className="text-sm">You have no pending booking requests at this moment.</p>
