              )}
            </div>
          </section>

          <section>
            <h2 className="text-xl font-bold text-gray-900 mb-4">Request History</h2>
            <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden opacity-80">
              <div className="p-4 bg-gray-50 border-b border-gray-100 text-xs font-bold text-gray-400 uppercase tracking-widest">Processed Applications</div>
              {bookings.filter(b => b.status !== 'PENDING').length > 0 ? (
                <div className="divide-y divide-gray-100">
                  {bookings.filter(b => b.status !== 'PENDING').map(booking => {
                    const house = houses.find(h => h.id === booking.houseId);
                    const tenant = MOCK_USERS.find(u => u.id === booking.tenantId);
                    return (
                      <div key={booking.id} className="p-4 flex items-center justify-between">
                         <div className="flex items-center gap-3">
                            <img src={tenant?.avatar} className="h-8 w-8 rounded-full" alt="" />
                            <span className="text-sm font-bold text-gray-700">{tenant?.name}</span>
                         </div>
                         <div className="text-xs text-gray-400">{house?.title}</div>
                         <span className={`px-2 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider ${
