                  <div>
                    <h4 className="text-sm font-extrabold text-gray-900 leading-tight">{house.title}</h4>
                    <p className="text-xs text-indigo-500 font-bold mt-1">${house.price}<span className="text-gray-400 font-normal">/mo</span></p>
