          <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-xl shadow-indigo-100 mt-8">
            <h3 className="text-lg font-bold mb-2">Performance Analytics</h3>
            <p className="text-indigo-100 text-sm mb-4">You've reached 94% occupancy rate this quarter!</p>
            <div className="w-full bg-indigo-700 h-2 rounded-full overflow-hidden">
               <div className="bg-white h-full w-[94%]"></div>
            </div>
            <button className="mt-4 text-xs font-bold text-white bg-indigo-500/50 hover:bg-indigo-500 px-4 py-2 rounded-lg transition-colors">
              View Reports
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderMyBookings = () => (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="mb-10">
        <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Your Journey</h1>
        <p className="mt-2 text-gray-500">Track your application status and manage upcoming moves.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {bookings.filter(b => b.tenantId === currentUser.id).length > 0 ? (
          bookings.filter(b => b.tenantId === currentUser.id).map(booking => {
            const house = houses.find(h => h.id === booking.houseId);
            return (
              <div key={booking.id} className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden transition-all hover:shadow-lg">
                <div className="relative h-48">
                  <img src={house?.images[0]} className="w-full h-full object-cover" alt="" />
                  <div className="absolute top-4 right-4">
                    <span className={`px-4 py-1.5 rounded-full text-xs font-bold shadow-lg ${
                      booking.status === 'PENDING' ? 'bg-amber-100 text-amber-700' :
                      booking.status === 'CONFIRMED' ? 'bg-green-600 text-white' : 'bg-red-100 text-red-700'
