                    <MapPin className="w-4 h-4 text-indigo-500" />
                    {house?.location}
                  </div>
                  <div className="flex justify-between items-center pt-4 border-t border-gray-100">
                    <div>
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Lease Amount</p>
                      <p className="text-lg font-bold text-indigo-600">${booking.totalPrice}<span className="text-xs font-normal">/mo</span></p>
                    </div>
                    <div className="text-right">
                       <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Move-in Date</p>
                       <p className="text-sm font-bold text-gray-700">{new Date(booking.startDate).toLocaleDateString()}</p>
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        ) : (
          <div className="col-span-full py-20 text-center bg-white rounded-3xl border border-dashed border-gray-300">
            <ShoppingBag className="h-12 w-12 text-gray-200 mx-auto mb-4" />
            <h3 className="text-lg font-bold text-gray-900">No active bookings</h3>
            <p className="text-gray-500 mb-6">You haven't applied for any sanctuary yet.</p>
            <button 
              onClick={() => setCurrentPage('MARKETPLACE')}
              className="px-6 py-2.5 bg-indigo-600 text-white font-bold rounded-xl"
            >
              Browse Homes
            </button>
          </div>
        )}
      </div>
    </div>
  );

  const renderPage = () => {
    switch(currentPage) {
      case 'MARKETPLACE': return renderMarketplace();
      case 'DASHBOARD': return renderDashboard();
      case 'ABOUT': return <AboutUs />;
      case 'CONTACT': return <ContactUs />;
      case 'MY_BOOKINGS': return renderMyBookings();
      default: return renderMarketplace();
    }
  };

  return (
    <div className="min-h-screen pb-20 bg-slate-50">
      <Navbar 
        currentRole={currentUser.role} 
        currentPage={currentPage}
        currentUser={currentUser}
        onPageChange={(page) => setCurrentPage(page)}
        onRoleChange={(role) => {
          const newUser = MOCK_USERS.find(u => u.role === role) || MOCK_USERS[0];
          setCurrentUser(newUser);
          // Redirect to home page of that role
          if (role === 'TENANT') setCurrentPage('MARKETPLACE');
          else setCurrentPage('DASHBOARD');
        }}
      />

      {renderPage()}

      {selectedHouse && (
        <BookingModal 
          house={selectedHouse} 
          user={currentUser}
          onClose={() => setSelectedHouse(null)}
          onSubmit={handleBookingSubmit}
        />
      )}

      {/* Persistent Mobile Tab Bar (Contextual) */}
      <div className="fixed bottom-0 left-0 right-0 glass border-t border-gray-200 p-3 md:hidden flex justify-around shadow-2xl">
        <button 
          onClick={() => setCurrentPage(currentUser.role === 'TENANT' ? 'MARKETPLACE' : 'DASHBOARD')}
          className={`p-2 flex flex-col items-center ${currentPage === 'MARKETPLACE' || currentPage === 'DASHBOARD' ? 'text-indigo-600' : 'text-gray-400'}`}
        >
          {currentUser.role === 'TENANT' ? <LayoutGrid className="h-6 w-6" /> : <LayoutDashboard className="h-6 w-6" />}
          <span className="text-[10px] font-bold mt-1">{currentUser.role === 'TENANT' ? 'Explore' : 'Panel'}</span>
        </button>
        {currentUser.role === 'TENANT' && (
          <button 
            onClick={() => setCurrentPage('MY_BOOKINGS')}
            className={`p-2 flex flex-col items-center ${currentPage === 'MY_BOOKINGS' ? 'text-indigo-600' : 'text-gray-400'}`}
          >
            <Clock className="h-6 w-6" />
            <span className="text-[10px] font-bold mt-1">Status</span>
          </button>
        )}
        <button 
          onClick={() => setCurrentPage('ABOUT')}
          className={`p-2 flex flex-col items-center ${currentPage === 'ABOUT' ? 'text-indigo-600' : 'text-gray-400'}`}
        >
          <Info className="h-6 w-6" />
          <span className="text-[10px] font-bold mt-1">Story</span>
        </button>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import Navbar from './components/Navbar';
import PropertyCard from './components/PropertyCard';
import BookingModal from './components/BookingModal';
import AboutUs from './components/AboutUs';
import ContactUs from './components/ContactUs';
import { MOCK_HOUSES, MOCK_USERS } from './constants';
import { House, UserRole, Booking, SearchFilters, User, Page } from './types';
// Fixed: Added missing icon imports ShoppingBag, LayoutDashboard, and Info
import { Search, Filter, CheckCircle2, XCircle, Clock, LayoutGrid, List, User as UserIcon, Building2, MapPin, Calendar, ShoppingBag, LayoutDashboard, Info } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]);
  const [currentPage, setCurrentPage] = useState<Page>('MARKETPLACE');
  const [houses, setHouses] = useState<House[]>(MOCK_HOUSES);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedHouse, setSelectedHouse] = useState<House | null>(null);

  // Filter States
  const [filters, setFilters] = useState<SearchFilters>({
    location: '',
    minPrice: '',
    maxPrice: '',
    type: 'All',
    bedrooms: '',
    amenities: []
  });

  // Filter Logic
  const filteredHouses = useMemo(() => {
    return houses.filter(h => {
      const matchLoc = h.location.toLowerCase().includes(filters.location.toLowerCase());
      const matchMin = filters.minPrice === '' || h.price >= filters.minPrice;
      const matchMax = filters.maxPrice === '' || h.price <= filters.maxPrice;
      const matchType = filters.type === 'All' || h.type === filters.type;
      const matchBeds = filters.bedrooms === '' || h.bedrooms === Number(filters.bedrooms);
      return matchLoc && matchMin && matchMax && matchType && matchBeds;
    });
  }, [houses, filters]);

  const handleBookingSubmit = (startDate: string, endDate: string) => {
    if (!selectedHouse) return;

    const newBooking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      houseId: selectedHouse.id,
      tenantId: currentUser.id,
      status: 'PENDING',
      startDate,
      endDate,
      totalPrice: selectedHouse.price, 
      createdAt: new Date().toISOString()
    };

    setBookings([newBooking, ...bookings]);
    setSelectedHouse(null);
    setCurrentPage('MY_BOOKINGS');
  };

  const updateBookingStatus = (bookingId: string, status: Booking['status']) => {
    setBookings(prev => prev.map(b => b.id === bookingId ? { ...b, status } : b));

    if (status === 'CONFIRMED') {
      const booking = bookings.find(b => b.id === bookingId);
      if (booking) {
        setHouses(prev => prev.map(h => h.id === booking.houseId ? { ...h, isAvailable: false } : h));
      }
    }
  };

  const toggleHouseAvailability = (houseId: string) => {
    setHouses(prev => prev.map(h => h.id === houseId ? { ...h, isAvailable: !h.isAvailable } : h));
  };

  // Views
  const renderMarketplace = () => (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Find your next home</h1>
          <p className="mt-2 text-gray-500">Discover premium properties managed by verified landlords and agents.</p>
        </div>
        <div className="flex items-center gap-2 text-sm text-gray-400 font-medium">
          <span className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-full">{filteredHouses.length} properties found</span>
        </div>
      </div>

      {/* Advanced Filter Bar */}
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6 mb-10 sticky top-20 z-40 transition-shadow hover:shadow-md">
