                  <img src={house?.images[0]} className="w-full h-full object-cover" alt="" />
                  <div className="absolute top-4 right-4">
                    <span className={`px-4 py-1.5 rounded-full text-xs font-bold shadow-lg ${
                      booking.status === 'PENDING' ? 'bg-amber-100 text-amber-700' :
                      booking.status === 'CONFIRMED' ? 'bg-green-600 text-white' : 'bg-red-100 text-red-700'
                    }`}>
                      {booking.status}
                    </span>
                  </div>
                </div>
                <div className="p-6">
                  <h3 className="text-xl font-bold text-gray-900 mb-2">{house?.title}</h3>
                  <div className="flex items-center text-sm text-gray-500 mb-4 gap-1.5 font-medium">
                    <MapPin className="w-4 h-4 text-indigo-500" />
                    {house?.location}
                  </div>
                  <div className="flex justify-between items-center pt-4 border-t border-gray-100">
                    <div>
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Lease Amount</p>
                      <p className="text-lg font-bold text-indigo-600">${booking.totalPrice}<span className="text-xs font-normal">/mo</span></p>
                    </div>
                    <div className="text-right">
                       <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Move-in Date</p>
                       <p className="text-sm font-bold text-gray-700">{new Date(booking.startDate).toLocaleDateString()}</p>
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        ) : (
          <div className="col-span-full py-20 text-center bg-white rounded-3xl border border-dashed border-gray-300">
            <ShoppingBag className="h-12 w-12 text-gray-200 mx-auto mb-4" />
            <h3 className="text-lg font-bold text-gray-900">No active bookings</h3>
            <p className="text-gray-500 mb-6">You haven't applied for any sanctuary yet.</p>
            <button 
              onClick={() => setCurrentPage('MARKETPLACE')}
              className="px-6 py-2.5 bg-indigo-600 text-white font-bold rounded-xl"
            >
              Browse Homes
            </button>
          </div>
        )}
      </div>
    </div>
  );

  const renderPage = () => {
    switch(currentPage) {
      case 'MARKETPLACE': return renderMarketplace();
      case 'DASHBOARD': return renderDashboard();
      case 'ABOUT': return <AboutUs />;
      case 'CONTACT': return <ContactUs />;
      case 'MY_BOOKINGS': return renderMyBookings();
      default: return renderMarketplace();
    }
  };

  return (
    <div className="min-h-screen pb-20 bg-slate-50">
      <Navbar 
        currentRole={currentUser.role} 
        currentPage={currentPage}
        currentUser={currentUser}
        onPageChange={(page) => setCurrentPage(page)}
        onRoleChange={(role) => {
          const newUser = MOCK_USERS.find(u => u.role === role) || MOCK_USERS[0];
          setCurrentUser(newUser);
          // Redirect to home page of that role
          if (role === 'TENANT') setCurrentPage('MARKETPLACE');
          else setCurrentPage('DASHBOARD');
        }}
      />

      {renderPage()}

      {selectedHouse && (
        <BookingModal 
          house={selectedHouse} 
          user={currentUser}
          onClose={() => setSelectedHouse(null)}
          onSubmit={handleBookingSubmit}
        />
      )}

      {/* Persistent Mobile Tab Bar (Contextual) */}
      <div className="fixed bottom-0 left-0 right-0 glass border-t border-gray-200 p-3 md:hidden flex justify-around shadow-2xl">
        <button 
          onClick={() => setCurrentPage(currentUser.role === 'TENANT' ? 'MARKETPLACE' : 'DASHBOARD')}
          className={`p-2 flex flex-col items-center ${currentPage === 'MARKETPLACE' || currentPage === 'DASHBOARD' ? 'text-indigo-600' : 'text-gray-400'}`}
        >
          {currentUser.role === 'TENANT' ? <LayoutGrid className="h-6 w-6" /> : <LayoutDashboard className="h-6 w-6" />}
          <span className="text-[10px] font-bold mt-1">{currentUser.role === 'TENANT' ? 'Explore' : 'Panel'}</span>
        </button>
        {currentUser.role === 'TENANT' && (
          <button 
            onClick={() => setCurrentPage('MY_BOOKINGS')}
            className={`p-2 flex flex-col items-center ${currentPage === 'MY_BOOKINGS' ? 'text-indigo-600' : 'text-gray-400'}`}
          >
            <Clock className="h-6 w-6" />
            <span className="text-[10px] font-bold mt-1">Status</span>
          </button>
        )}
        <button 
          onClick={() => setCurrentPage('ABOUT')}
          className={`p-2 flex flex-col items-center ${currentPage === 'ABOUT' ? 'text-indigo-600' : 'text-gray-400'}`}
        >
          <Info className="h-6 w-6" />
          <span className="text-[10px] font-bold mt-1">Story</span>
        </button>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { House } from "../types";

// Fixed: Using process.env.API_KEY directly for initialization as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  /**
   * Generates a creative and enticing marketing description for a house listing.
   */
  async generateListingDescription(house: Partial<House>) {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Act as a professional real estate copywriter. Create a compelling, detailed marketing description for the following property:
        Title: ${house.title}
        Price: $${house.price}/month
        Type: ${house.type}
        Location: ${house.location}
        Beds/Baths: ${house.bedrooms}/${house.bathrooms}
        Amenities: ${house.amenities?.join(', ')}

        The description should be engaging, highlight the best features, and target the right demographic.`,
      });
      return response.text;
    } catch (error) {
      console.error("Gemini Error:", error);
      return "Unable to generate description at this time.";
    }
  },

  /**
   * AI-powered search assistant to help customers find homes based on natural language.
   */
  async findMatchingHomes(query: string, availableHouses: House[]) {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `You are a real estate expert assistant. A customer is looking for a home with this request: "${query}".
        Based on our database of houses: ${JSON.stringify(availableHouses)},
        Return a JSON array of the IDs of the houses that best match this request, ordered by relevance.
        Only return the JSON array of strings.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        }
      });
      return JSON.parse(response.text || '[]');
    } catch (error) {
      console.error("Gemini Error:", error);
      return [];
    }
  }
};

export type UserRole = 'TENANT' | 'LANDLORD' | 'AGENT' | 'ADMIN';
export type Page = 'MARKETPLACE' | 'DASHBOARD' | 'ABOUT' | 'CONTACT' | 'MY_BOOKINGS' | 'SETTINGS' | 'USER_MANAGEMENT';
export type AuthPage = 'LOGIN' | 'SIGNUP' | 'RESET_PASSWORD' | 'NONE';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar: string;
  phone?: string;
  joinedDate: string;
  status: 'ACTIVE' | 'SUSPENDED';
}

export interface House {
  id: string;
  title: string;
  description: string;
  price: number;
  location: string;
  type: 'Apartment' | 'House' | 'Studio' | 'Villa';
  bedrooms: number;
  bathrooms: number;
  images: string[];
  isAvailable: boolean;
  amenities: string[];
  ownerId: string;
  agentId?: string;
}

export interface Booking {
  id: string;
  houseId: string;
  tenantId: string;
  status: 'PENDING' | 'CONFIRMED' | 'REJECTED' | 'CANCELLED';
  startDate: string;
  endDate: string;
  totalPrice: number;
  createdAt: string;
}

export interface SearchFilters {
  location: string;
  minPrice: number | '';
  maxPrice: number | '';
  type: string;
  bedrooms: number | '';
  amenities: string[];
}

import React, { useState } from 'react';
import { AuthPage, UserRole } from '../types';
import { Home, Mail, Lock, User, Phone, ArrowLeft, Loader2 } from 'lucide-react';

interface AuthOverlayProps {
  view: AuthPage;
  onClose: () => void;
  onLogin: (email: string, role: UserRole) => void;
  onNavigate: (view: AuthPage) => void;
}

const AuthOverlay: React.FC<AuthOverlayProps> = ({ view, onLogin, onNavigate }) => {
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>('TENANT');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      if (view === 'LOGIN' || view === 'SIGNUP') {
        onLogin(email, role);
      } else {
        alert('Password reset instructions sent!');
        onNavigate('LOGIN');
      }
    }, 1200);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 backdrop-blur-md p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in slide-in-from-bottom-8 duration-500">
        <div className="bg-indigo-600 p-8 text-center text-white relative">
          <div className="bg-white/20 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4 backdrop-blur-sm">
            <Home className="w-8 h-8" />
          </div>
          <h2 className="text-3xl font-extrabold tracking-tight">
            {view === 'LOGIN' ? 'Welcome Back' : view === 'SIGNUP' ? 'Join UrbanNest' : 'Reset Password'}
          </h2>
          <p className="text-indigo-100 mt-2">
            {view === 'LOGIN' ? 'Enter your credentials to continue' : view === 'SIGNUP' ? 'Create your rental ecosystem account' : 'We will help you recover access'}
          </p>
        </div>

        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-4">
            {view === 'SIGNUP' && (
              <div className="space-y-4">
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                  <input type="text" placeholder="Full Name" required className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
                </div>
                <div className="relative">
                  <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                  <input type="tel" placeholder="Phone Number" required className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
                </div>
              </div>
            )}

            <div className="relative">
              <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input 
                type="email" 
                placeholder="Email Address" 
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required 
                className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all" 
              />
            </div>

            {view !== 'RESET_PASSWORD' && (
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input type="password" placeholder="Password" required className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
              </div>
            )}

            {(view === 'LOGIN' || view === 'SIGNUP') && (
              <div className="space-y-2 pt-2">
                <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Log in as</label>
                <div className="grid grid-cols-2 gap-2">
                  {(['TENANT', 'LANDLORD', 'AGENT', 'ADMIN'] as UserRole[]).map((r) => (
                    <button
                      key={r}
                      type="button"
                      onClick={() => setRole(r)}
                      className={`py-3 px-4 rounded-xl text-xs font-bold transition-all border-2 ${
                        role === r ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-gray-100 text-gray-400 hover:border-gray-200'
                      }`}
                    >
                      {r}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {view === 'LOGIN' && (
              <div className="text-right">
                <button type="button" onClick={() => onNavigate('RESET_PASSWORD')} className="text-xs font-bold text-indigo-600 hover:underline">
                  Forgot password?
                </button>
              </div>
            )}

            <button
              disabled={loading}
              type="submit"
              className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-[0.98] transition-all flex items-center justify-center gap-2"
            >
              {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : view === 'LOGIN' ? 'Login' : view === 'SIGNUP' ? 'Sign Up' : 'Send Instructions'}
            </button>
          </form>

          <div className="mt-8 text-center">
            {view === 'LOGIN' ? (
              <p className="text-sm text-gray-500">
                Don't have an account?{' '}
                <button onClick={() => onNavigate('SIGNUP')} className="text-indigo-600 font-bold hover:underline">Create one</button>
              </p>
            ) : (
              <button onClick={() => onNavigate('LOGIN')} className="inline-flex items-center gap-2 text-sm text-gray-500 font-bold hover:text-indigo-600 transition-colors">
                <ArrowLeft className="w-4 h-4" /> Back to Login
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuthOverlay;

import React, { useState, useMemo, useEffect } from 'react';
import Navbar from './components/Navbar';
import PropertyCard from './components/PropertyCard';
import BookingModal from './components/BookingModal';
import AboutUs from './components/AboutUs';
import ContactUs from './components/ContactUs';
import AuthOverlay from './components/AuthOverlay';
import Settings from './components/Settings';
import { MOCK_HOUSES, MOCK_USERS } from './constants';
