        <div>
          <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Management Console</h1>
          <p className="text-gray-500 mt-1">Hello, {currentUser?.name}. {currentUser?.role === 'ADMIN' ? 'System-wide overview.' : 'Managing your portfolio.'}</p>
        </div>
        <button 
