                <th className="p-4 text-[10px] font-black uppercase text-slate-400">Role</th>
                <th className="p-4 text-[10px] font-black uppercase text-slate-400">Status</th>
                <th className="p-4 text-[10px] font-black uppercase text-slate-400">Joined</th>
                <th className="p-4 text-[10px] font-black uppercase text-slate-400 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {users.map(u => (
                <tr key={u.id} className="hover:bg-slate-50/30 transition-colors">
                  <td className="p-4">
                    <div className="flex items-center gap-3">
                      <img src={u.avatar} className="w-10 h-10 rounded-full" />
                      <div>
                        <p className="text-sm font-bold text-slate-900">{u.name}</p>
                        <p className="text-xs text-slate-400">{u.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="p-4"><span className="text-xs font-bold text-slate-600 bg-slate-100 px-2 py-1 rounded-lg uppercase">{u.role}</span></td>
                  <td className="p-4">
                     <button 
                      onClick={() => updateUserStatus(u.id, u.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE')}
                      className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${u.status === 'ACTIVE' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}
                     >
                       {u.status}
                     </button>
                  </td>
                  <td className="p-4 text-xs font-bold text-slate-400">{u.joinedDate}</td>
                  <td className="p-4 text-right">
                    <button onClick={() => deleteUser(u.id)} className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 className="w-4 h-4" /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    switch(currentPage) {
      case 'MARKETPLACE': return renderMarketplace();
      case 'DASHBOARD': return renderDashboard();
      case 'USER_MANAGEMENT': return renderUserManagement();
      case 'ABOUT': return <AboutUs />;
      case 'CONTACT': return <ContactUs />;
      case 'MY_BOOKINGS': return currentUser?.role === 'TENANT' ? (
        <div className="max-w-7xl mx-auto px-4 py-8 animate-in fade-in duration-500">
           <h1 className="text-3xl font-black mb-8">My Rental Status</h1>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {bookings.filter(b => b.tenantId === currentUser.id).map(b => (
                <div key={b.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm relative overflow-hidden">
                   <div className={`absolute top-0 right-0 px-4 py-2 rounded-bl-2xl text-[10px] font-black uppercase tracking-widest ${b.status === 'CONFIRMED' ? 'bg-green-600 text-white' : 'bg-amber-100 text-amber-700'}`}>
                      {b.status}
                   </div>
                   <h3 className="text-xl font-bold mb-2">{houses.find(h => h.id === b.houseId)?.title}</h3>
                   <p className="text-xs text-slate-400 mb-6 flex items-center gap-1"><MapPin className="w-3 h-3" /> {houses.find(h => h.id === b.houseId)?.location}</p>
                   <div className="flex justify-between items-center pt-4 border-t border-slate-50">
                      <div><p className="text-[10px] font-black text-slate-300 uppercase">Rent</p><p className="font-bold text-indigo-600">${b.totalPrice}</p></div>
                      <div><p className="text-[10px] font-black text-slate-300 uppercase">Created</p><p className="font-bold text-slate-600">{new Date(b.createdAt).toLocaleDateString()}</p></div>
                   </div>
                </div>
              ))}
              {bookings.filter(b => b.tenantId === currentUser.id).length === 0 && (
                <div className="col-span-full py-20 text-center opacity-40"><p className="font-bold">No booking requests found.</p></div>
              )}
           </div>
        </div>
      ) : renderDashboard();
      case 'SETTINGS': return <Settings user={currentUser!} onLogout={handleLogout} />;
      default: return renderMarketplace();
    }
  };

  return (
    <div className="min-h-screen bg-slate-50/50 pb-20">
      <Navbar 
        currentRole={currentUser?.role || 'TENANT'} 
        currentPage={currentPage}
        currentUser={currentUser || { name: 'Guest', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Guest' } as User}
        onPageChange={setCurrentPage}
        onRoleChange={() => {}} // Controlled by Auth now
      />

      {renderContent()}

      {selectedHouse && currentUser && (
        <BookingModal 
          house={selectedHouse} 
          user={currentUser}
          onClose={() => setSelectedHouse(null)}
          onSubmit={handleBookingSubmit}
        />
      )}
    </div>
  );
};

