import React, { useState, useMemo, useEffect } from 'react';
import Navbar from './components/Navbar';
import PropertyCard from './components/PropertyCard';
import BookingModal from './components/BookingModal';
import AboutUs from './components/AboutUs';
import ContactUs from './components/ContactUs';
import AuthOverlay from './components/AuthOverlay';
import Settings from './components/Settings';
import { MOCK_HOUSES, MOCK_USERS } from './constants';
import { House, UserRole, Booking, SearchFilters, User, Page, AuthPage } from './types';
import { Search, Filter, CheckCircle2, XCircle, Clock, LayoutGrid, List, User as UserIcon, Building2, MapPin, Calendar, ShoppingBag, LayoutDashboard, Info, Plus, Trash2, Edit, ShieldAlert, MoreVertical } from 'lucide-react';
import { geminiService } from './services/geminiService';

const App: React.FC = () => {
  // Auth State
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authView, setAuthView] = useState<AuthPage>('LOGIN');

  // App State
  const [currentPage, setCurrentPage] = useState<Page>('MARKETPLACE');
  const [houses, setHouses] = useState<House[]>(MOCK_HOUSES);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [selectedHouse, setSelectedHouse] = useState<House | null>(null);
  const [isEditing, setIsEditing] = useState<House | null>(null);

  // Filter States
  const [filters, setFilters] = useState<SearchFilters>({
    location: '',
    minPrice: '',
    maxPrice: '',
    type: 'All',
    bedrooms: '',
    amenities: []
  });

  // Derived filtered houses
  const filteredHouses = useMemo(() => {
    return houses.filter(h => {
      const matchLoc = h.location.toLowerCase().includes(filters.location.toLowerCase());
      // Fixed: Adding type assertions to ensure comparison works with union type
      const matchMin = filters.minPrice === '' || h.price >= (filters.minPrice as number);
      const matchMax = filters.maxPrice === '' || h.price <= (filters.maxPrice as number);
      const matchType = filters.type === 'All' || h.type === filters.type;
      const matchBeds = filters.bedrooms === '' || h.bedrooms === Number(filters.bedrooms);
      return matchLoc && matchMin && matchMax && matchType && matchBeds;
    });
  }, [houses, filters]);

  // Auth Handlers
  const handleLogin = (email: string, role: UserRole) => {
    const user = users.find(u => u.email === email && u.role === role) || {
      id: Math.random().toString(36).substr(2, 9),
      name: email.split('@')[0],
      email: email,
      role: role,
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${email}`,
      joinedDate: new Date().toISOString().split('T')[0],
      status: 'ACTIVE'
    };
    setCurrentUser(user as User);
    setAuthView('NONE');
    setCurrentPage(role === 'TENANT' ? 'MARKETPLACE' : 'DASHBOARD');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setAuthView('LOGIN');
    setCurrentPage('MARKETPLACE');
  };

  // CRUD Handlers for Houses
  const saveHouse = async (houseData: Partial<House>) => {
    if (isEditing) {
      setHouses(prev => prev.map(h => h.id === isEditing.id ? { ...h, ...houseData } as House : h));
      setIsEditing(null);
    } else {
      const newHouse: House = {
        id: Math.random().toString(36).substr(2, 9),
        title: houseData.title || 'New Property',
        description: houseData.description || '',
        price: houseData.price || 0,
        location: houseData.location || 'Unknown',
        type: houseData.type || 'Apartment',
        bedrooms: houseData.bedrooms || 1,
        bathrooms: houseData.bathrooms || 1,
        images: houseData.images || ['https://images.unsplash.com/photo-1518780664697-55e3ad937233?auto=format&fit=crop&w=800&q=80'],
        isAvailable: true,
        amenities: houseData.amenities || [],
        ownerId: currentUser?.id || 'admin',
        agentId: currentUser?.role === 'AGENT' ? currentUser.id : undefined
      };
      setHouses([newHouse, ...houses]);
    }
  };

  const deleteHouse = (id: string) => {
    if (confirm('Are you sure you want to remove this property?')) {
      setHouses(prev => prev.filter(h => h.id !== id));
    }
  };

  // User Management
  const updateUserStatus = (userId: string, status: 'ACTIVE' | 'SUSPENDED') => {
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, status } : u));
  };

  const deleteUser = (userId: string) => {
    if (confirm('Delete this user? This action is permanent.')) {
      setUsers(prev => prev.filter(u => u.id !== userId));
    }
  };

  const handleBookingSubmit = (startDate: string, endDate: string) => {
    if (!selectedHouse || !currentUser) return;
    const newBooking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      houseId: selectedHouse.id,
      tenantId: currentUser.id,
      status: 'PENDING',
      startDate,
      endDate,
      totalPrice: selectedHouse.price, 
      createdAt: new Date().toISOString()
    };
    setBookings([newBooking, ...bookings]);
    setSelectedHouse(null);
    setCurrentPage('MY_BOOKINGS');
  };

  const updateBookingStatus = (bookingId: string, status: Booking['status']) => {
    setBookings(prev => prev.map(b => b.id === bookingId ? { ...b, status } : b));
    if (status === 'CONFIRMED') {
      const booking = bookings.find(b => b.id === bookingId);
      if (booking) setHouses(prev => prev.map(h => h.id === booking.houseId ? { ...h, isAvailable: false } : h));
    }
  };

  // Rendering logic
  if (authView !== 'NONE') {
    return <AuthOverlay view={authView} onLogin={handleLogin} onNavigate={setAuthView} onClose={() => setAuthView('NONE')} />;
  }

  const renderMarketplace = () => (
