        />
      )}
    </div>
  );
};

export default App;

export type UserRole = 'TENANT' | 'LANDLORD' | 'AGENT' | 'ADMIN';
export type Page = 
  | 'MARKETPLACE' 
  | 'DASHBOARD' 
  | 'ABOUT' 
  | 'CONTACT' 
  | 'MY_BOOKINGS' 
  | 'SETTINGS' 
  | 'MANAGEMENT_HOMES' 
  | 'TENANTS' 
  | 'AGENTS' 
  | 'LANDLORDS' 
  | 'REPORTS' 
  | 'CAMPAIGNS';

export type AuthPage = 'LOGIN' | 'SIGNUP' | 'RESET_PASSWORD' | 'NONE';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar: string;
  phone?: string;
  joinedDate: string;
  status: 'ACTIVE' | 'SUSPENDED';
}

export interface House {
  id: string;
  title: string;
  description: string;
  price: number;
  location: string;
  type: 'Apartment' | 'House' | 'Studio' | 'Villa';
  bedrooms: number;
  bathrooms: number;
  images: string[];
  isAvailable: boolean;
  amenities: string[];
  ownerId: string;
  agentId?: string;
}

export interface Campaign {
  id: string;
  name: string;
  description: string;
  status: 'ACTIVE' | 'PAUSED' | 'COMPLETED';
  budget: number;
  targetAudience: string;
  startDate: string;
}

export interface Booking {
  id: string;
  houseId: string;
  tenantId: string;
  status: 'PENDING' | 'CONFIRMED' | 'REJECTED' | 'CANCELLED';
  startDate: string;
  endDate: string;
  totalPrice: number;
  createdAt: string;
}

export interface SearchFilters {
  location: string;
  minPrice: number | '';
  maxPrice: number | '';
  type: string;
  bedrooms: number | '';
  amenities: string[];
}

