                   </div>
                   <div className="mb-6"><img src={houses.find(h => h.id === b.houseId)?.images[0]} className="w-full h-40 object-cover rounded-2xl group-hover:scale-105 transition-transform" /></div>
                   <h3 className="text-2xl font-black text-slate-900 mb-2">{houses.find(h => h.id === b.houseId)?.title}</h3>
                   <p className="text-sm text-slate-400 mb-6 flex items-center gap-1.5 font-medium"><MapPin className="w-4 h-4 text-indigo-500" /> {houses.find(h => h.id === b.houseId)?.location}</p>
                   <div className="flex justify-between items-center pt-6 border-t border-slate-50">
