            ].map((act, i) => (
              <div key={i} className="space-y-2">
                <div className="flex justify-between text-xs font-bold">
                  <span className="text-slate-500">{act.label}</span>
                  <span className="text-slate-900">{act.val.toLocaleString()}</span>
                </div>
                <div className="h-1.5 w-full bg-slate-50 rounded-full overflow-hidden">
                  <div className={`h-full bg-${act.color}-500`} style={{ width: `${act.pct}%` }}></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  const renderManagementTable = (type: 'HOMES' | 'TENANTS' | 'LANDLORDS' | 'AGENTS' | 'CAMPAIGNS') => {
    let data: any[] = [];
    let title = "";
    let onAdd = () => {};

    if (type === 'HOMES') {
      data = houses.filter(h => currentUser?.role === 'ADMIN' || h.ownerId === currentUser?.id);
      title = "Property Inventory";
      onAdd = () => setIsEditingHouse({} as House);
    } else if (type === 'TENANTS') {
      data = users.filter(u => u.role === 'TENANT');
      title = "Verified Tenants";
      onAdd = () => setIsEditingUser({ role: 'TENANT' } as User);
    } else if (type === 'LANDLORDS') {
      data = users.filter(u => u.role === 'LANDLORD');
      title = "Property Owners";
      onAdd = () => setIsEditingUser({ role: 'LANDLORD' } as User);
    } else if (type === 'AGENTS') {
      data = users.filter(u => u.role === 'AGENT');
      title = "Active Agents";
      onAdd = () => setIsEditingUser({ role: 'AGENT' } as User);
    } else if (type === 'CAMPAIGNS') {
      data = campaigns;
      title = "Marketing Campaigns";
      onAdd = () => setIsEditingCampaign({} as Campaign);
    }

    return (
      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden animate-in fade-in duration-500">
        <div className="p-8 border-b border-slate-50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-2xl font-black text-slate-900">{title}</h2>
            <p className="text-slate-400 text-sm mt-1">Manage and update your records in real-time.</p>
          </div>
          <button 
            onClick={onAdd}
            className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
          >
            {type === 'HOMES' ? <Plus className="w-5 h-5"/> : (type === 'CAMPAIGNS' ? <Megaphone className="w-5 h-5"/> : <UserPlus className="w-5 h-5"/>)}
            Add {type.slice(0, -1)}
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50">
                <th className="p-5 text-[10px] font-black uppercase text-slate-400 tracking-widest">Details</th>
                {type === 'CAMPAIGNS' ? (
                  <>
                    <th className="p-5 text-[10px] font-black uppercase text-slate-400 tracking-widest">Budget</th>
                    <th className="p-5 text-[10px] font-black uppercase text-slate-400 tracking-widest">Audience</th>
                  </>
                ) : (
                  <>
                    <th className="p-5 text-[10px] font-black uppercase text-slate-400 tracking-widest">{type === 'HOMES' ? 'Pricing' : 'Contact'}</th>
                    <th className="p-5 text-[10px] font-black uppercase text-slate-400 tracking-widest">{type === 'HOMES' ? 'Location' : 'Status'}</th>
                  </>
                )}
                <th className="p-5 text-[10px] font-black uppercase text-slate-400 tracking-widest text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {data.map((item) => (
                <tr key={item.id} className="hover:bg-slate-50/30 transition-colors group">
                  <td className="p-5">
                    <div className="flex items-center gap-4">
                      {item.images || item.avatar ? (
                        <img src={item.images ? item.images[0] : item.avatar} className="w-12 h-12 rounded-2xl object-cover shadow-sm" />
                      ) : <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600"><Megaphone className="w-5 h-5"/></div>}
                      <div>
                        <p className="text-sm font-black text-slate-900">{item.title || item.name}</p>
                        <p className="text-xs text-slate-400 font-medium">{item.email || item.type || item.description?.substring(0, 30) + "..."}</p>
                      </div>
                    </div>
                  </td>
                  <td className="p-5 font-bold text-sm text-slate-700">
                    {item.price ? `$${item.price}` : (item.budget ? `$${item.budget}` : (item.phone || item.email))}
                  </td>
                  <td className="p-5">
                    {item.location || (
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${
                        item.status === 'ACTIVE' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                      }`}>
                        {item.status || (item.isAvailable ? 'Active' : 'Reserved')}
                      </span>
                    )}
                  </td>
                  <td className="p-5 text-right">
                    <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => {
                          if (type === 'HOMES') setIsEditingHouse(item);
                          else if (type === 'CAMPAIGNS') setIsEditingCampaign(item);
                          else setIsEditingUser(item);
                        }} 
                        className="p-2.5 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"
                      >
                        <Edit className="w-4 h-4"/>
                      </button>
                      <button 
                        onClick={() => {
                          if (confirm(`Delete this ${type.slice(0, -1)}?`)) {
                             if (type === 'HOMES') setHouses(prev => prev.filter(h => h.id !== item.id));
                             else if (type === 'CAMPAIGNS') setCampaigns(prev => prev.filter(c => c.id !== item.id));
                             else setUsers(prev => prev.filter(u => u.id !== item.id));
                          }
                        }}
                        className="p-2.5 bg-red-50 text-red-600 rounded-xl hover:bg-red-600 hover:text-white transition-all"
                      >
                        <Trash2 className="w-4 h-4"/>
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch(currentPage) {
      case 'MARKETPLACE': return renderMarketplace();
      case 'DASHBOARD': return renderDashboardOverview();
      case 'MANAGEMENT_HOMES': return renderManagementTable('HOMES');
      case 'TENANTS': return renderManagementTable('TENANTS');
      case 'LANDLORDS': return renderManagementTable('LANDLORDS');
      case 'AGENTS': return renderManagementTable('AGENTS');
      case 'CAMPAIGNS': return renderManagementTable('CAMPAIGNS');
      case 'REPORTS': return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in duration-500">
          <div className="bg-indigo-600 rounded-[2.5rem] p-10 text-white shadow-2xl shadow-indigo-100">
            <h2 className="text-3xl font-black mb-4">Financial Overview</h2>
            <p className="text-indigo-100 font-medium mb-10">Total lease agreements processed this year.</p>
            <div className="flex items-end gap-2 mb-8">
               <span className="text-5xl font-black">$452,100</span>
               <span className="text-sm font-bold bg-white/20 px-3 py-1 rounded-full mb-2">+18% YoY</span>
            </div>
            <div className="grid grid-cols-7 gap-2 items-end h-32">
               {[40, 60, 45, 90, 70, 85, 100].map((h, i) => (
                 <div key={i} className="bg-white/30 rounded-t-lg transition-all hover:bg-white" style={{ height: `${h}%` }}></div>
               ))}
            </div>
          </div>
          <div className="bg-white rounded-[2.5rem] border border-slate-100 p-10 shadow-sm flex flex-col justify-between">
            <div>
              <h2 className="text-3xl font-black text-slate-900 mb-2">Lead Sources</h2>
              <p className="text-slate-400 font-medium">Where your tenants are coming from.</p>
            </div>
            <div className="space-y-6 my-10">
               {[
                 { label: 'Google Search', pct: 65 },
                 { label: 'Referrals', pct: 15 },
                 { label: 'Direct Listings', pct: 20 }
               ].map((s, i) => (
                 <div key={i} className="space-y-2">
                   <div className="flex justify-between text-xs font-bold text-slate-700 uppercase tracking-widest">
                     <span>{s.label}</span>
                     <span>{s.pct}%</span>
                   </div>
                   <div className="h-2 bg-slate-50 rounded-full overflow-hidden">
                     <div className="h-full bg-indigo-600" style={{ width: `${s.pct}%` }}></div>
                   </div>
                 </div>
               ))}
            </div>
          </div>
        </div>
      );
      case 'ABOUT': return <AboutUs />;
      case 'CONTACT': return <ContactUs />;
      case 'SETTINGS': return <Settings user={currentUser!} onLogout={handleLogout} />;
      case 'MY_BOOKINGS': return (
        <div className="max-w-7xl mx-auto px-4 py-12 animate-in fade-in duration-500">
           <h1 className="text-4xl font-black mb-12">My Rental Application Journey</h1>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
              {bookings.filter(b => b.tenantId === currentUser?.id).map(b => (
                <div key={b.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative overflow-hidden group">
                   <div className={`absolute top-0 right-0 px-6 py-3 rounded-bl-3xl text-[10px] font-black uppercase tracking-widest ${b.status === 'CONFIRMED' ? 'bg-green-600 text-white' : 'bg-amber-100 text-amber-700'}`}>
                      {b.status}
                   </div>
                   <div className="mb-6"><img src={houses.find(h => h.id === b.houseId)?.images[0]} className="w-full h-40 object-cover rounded-2xl group-hover:scale-105 transition-transform" /></div>
                   <h3 className="text-2xl font-black text-slate-900 mb-2">{houses.find(h => h.id === b.houseId)?.title}</h3>
                   <p className="text-sm text-slate-400 mb-6 flex items-center gap-1.5 font-medium"><MapPin className="w-4 h-4 text-indigo-500" /> {houses.find(h => h.id === b.houseId)?.location}</p>
                   <div className="flex justify-between items-center pt-6 border-t border-slate-50">
                      <div><p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Rent</p><p className="text-xl font-black text-indigo-600">${b.totalPrice}</p></div>
                      <div><p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Applied On</p><p className="font-bold text-slate-600">{new Date(b.createdAt).toLocaleDateString()}</p></div>
                   </div>
                </div>
              ))}
              {bookings.filter(b => b.tenantId === currentUser?.id).length === 0 && (
                <div className="col-span-full py-24 text-center border-4 border-dashed border-slate-100 rounded-[3rem] opacity-50"><ShoppingBag className="w-12 h-12 mx-auto mb-4 text-slate-300"/><p className="text-lg font-black text-slate-400">Your haven history is currently empty.</p></div>
              )}
           </div>
        </div>
      );
      default: return renderMarketplace();
    }
  };

  return (
    <div className={`min-h-screen bg-slate-50/50 ${isManagementMode ? 'pl-72' : ''}`}>
      {!isManagementMode && authView === 'NONE' && (
        <Navbar 
          currentRole={currentUser?.role || 'TENANT'} 
          currentPage={currentPage}
          currentUser={currentUser || { name: 'Guest', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Guest' } as User}
          onPageChange={setCurrentPage}
          onRoleChange={() => {}} 
        />
      )}

      {isManagementMode && (
        <Sidebar 
          currentPage={currentPage} 
          onPageChange={setCurrentPage} 
          userRole={currentUser!.role} 
          onLogout={handleLogout}
        />
      )}

      {authView !== 'NONE' ? (
        <AuthOverlay view={authView} onLogin={handleLogin} onNavigate={setAuthView} onClose={() => {}} />
      ) : (
        <main className={`${isManagementMode ? 'p-12 max-w-[1400px] mx-auto' : ''}`}>
          {renderContent()}
        </main>
      )}

      {selectedHouse && currentUser && (
        <BookingModal house={selectedHouse} user={currentUser} onClose={() => setSelectedHouse(null)} onSubmit={handleBookingSubmit} />
      )}

      {/* MODAL FORMS FOR CRUD */}
      {isEditingHouse && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
           <div className="bg-white w-full max-w-xl rounded-[3rem] p-10 shadow-2xl animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-8">
                <h2 className="text-3xl font-black text-slate-900">{isEditingHouse.id ? 'Refine Property' : 'Enlist New Haven'}</h2>
                <button onClick={() => setIsEditingHouse(null)} className="p-2 text-slate-400 hover:text-slate-600 bg-slate-50 rounded-full"><X className="w-6 h-6"/></button>
              </div>
              <form onSubmit={(e) => { e.preventDefault(); saveHouse(isEditingHouse); }} className="space-y-6">
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Title</label>
                   <input placeholder="Sunset Villa..." value={isEditingHouse.title || ''} onChange={e => setIsEditingHouse({...isEditingHouse, title: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" required />
                 </div>
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rent ($/mo)</label>
                      <input type="number" placeholder="2500" value={isEditingHouse.price || ''} onChange={e => setIsEditingHouse({...isEditingHouse, price: Number(e.target.value)})} className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" required />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Location</label>
                      <input placeholder="Manhattan, NY" value={isEditingHouse.location || ''} onChange={e => setIsEditingHouse({...isEditingHouse, location: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" required />
                    </div>
                 </div>
                 <button type="submit" className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all text-lg">Commit Records</button>
              </form>
           </div>
        </div>
      )}

      {isEditingUser && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-8">
                <h2 className="text-3xl font-black text-slate-900">{isEditingUser.id ? 'Update Member' : `Register ${isEditingUser.role}`}</h2>
                <button onClick={() => setIsEditingUser(null)} className="p-2 text-slate-400 hover:text-slate-600 bg-slate-50 rounded-full"><X className="w-6 h-6"/></button>
              </div>
              <form onSubmit={(e) => { e.preventDefault(); saveUser(isEditingUser); }} className="space-y-6">
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
                   <input placeholder="Jane Cooper" value={isEditingUser.name || ''} onChange={e => setIsEditingUser({...isEditingUser, name: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" required />
                 </div>
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email</label>
                   <input type="email" placeholder="jane@example.com" value={isEditingUser.email || ''} onChange={e => setIsEditingUser({...isEditingUser, email: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" required />
                 </div>
                 <button type="submit" className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all text-lg">Save Member Data</button>
              </form>
           </div>
        </div>
      )}

      {isEditingCampaign && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-8">
                <h2 className="text-3xl font-black text-slate-900">{isEditingCampaign.id ? 'Optimize Campaign' : 'Initiate Outreach'}</h2>
                <button onClick={() => setIsEditingCampaign(null)} className="p-2 text-slate-400 hover:text-slate-600 bg-slate-50 rounded-full"><X className="w-6 h-6"/></button>
              </div>
              <form onSubmit={(e) => { e.preventDefault(); saveCampaign(isEditingCampaign); }} className="space-y-6">
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Campaign Title</label>
                   <input placeholder="Q4 Market Boost" value={isEditingCampaign.name || ''} onChange={e => setIsEditingCampaign({...isEditingCampaign, name: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" required />
                 </div>
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Allocated Budget</label>
                      <input type="number" placeholder="5000" value={isEditingCampaign.budget || ''} onChange={e => setIsEditingCampaign({...isEditingCampaign, budget: Number(e.target.value)})} className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" required />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Target Segment</label>
                      <input placeholder="Corporate" value={isEditingCampaign.targetAudience || ''} onChange={e => setIsEditingCampaign({...isEditingCampaign, targetAudience: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" required />
                    </div>
                 </div>
                 <button type="submit" className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all text-lg">Launch Campaign</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

